/* Banque de questions supplémentaires : français, chapitres 10, 11, f-texte, f-impersonnels, f-poesie, f-litterature, f-didactique, f-c4-themes */
window.BANK = window.BANK || {};

BANK['francais/10'] = [
  { q: "« Battez les œufs, ajoutez la farine puis enfournez pendant vingt minutes. » Ce texte est de type :", choices: ["narratif", "descriptif", "injonctif", "explicatif"], answer: 2, expl: "Les verbes à l’<b>impératif</b> donnent des consignes pour <b>faire faire</b> quelque chose : c’est un texte <b>injonctif</b> (ou prescriptif), comme une recette ou une règle du jeu. Il n’explique pas pourquoi, il dit quoi faire." },
  { q: "Lequel de ces mots est une marque de <b>modalisation</b> ?", choices: ["hier", "sans doute", "ici", "le lendemain"], answer: 1, expl: "<b>Sans doute</b> exprime le <b>degré de certitude</b> de l’énonciateur : c’est un modalisateur. Les autres sont des indicateurs de temps ou de lieu, qui situent l’énoncé sans exprimer de jugement." },
  { q: "« Un homme en manteau gris entra, posa son chapeau sur la table et fixa la porte. » Le point de vue est :", choices: ["interne", "externe", "omniscient"], answer: 1, expl: "On ne voit que des <b>gestes extérieurs</b>, comme à travers une caméra, sans rien savoir des pensées ni de l’identité de l’homme : c’est le point de vue <b>externe</b>." },
  { q: "« La salle entière applaudit. » La figure de style est :", choices: ["une hyperbole", "une métonymie", "un euphémisme", "une antithèse"], answer: 1, expl: "On désigne les <b>spectateurs</b> par le <b>lieu</b> où ils se trouvent (la salle) : c’est une <b>métonymie</b>, qui remplace un mot par un autre qui lui est lié logiquement." },
  { q: "« Il est petit par la taille mais grand par le cœur. » La figure de style est :", choices: ["un oxymore", "une comparaison", "une antithèse"], answer: 2, expl: "Les deux termes opposés (petit / grand) sont placés dans <b>deux parties différentes</b> de la phrase : c’est une <b>antithèse</b>. Piège : l’oxymore accole les contraires dans un même groupe (une « obscure clarté »)." },
  { q: "« Rome, l’unique objet de mon ressentiment ! / Rome, à qui vient ton bras d’immoler mon amant ! » (Corneille). La répétition de « Rome » en tête de vers est :", choices: ["une anaphore", "une allitération", "une métonymie", "une litote"], answer: 0, expl: "La reprise d’un même mot <b>en début de vers</b> ou de phrase est une <b>anaphore</b>. Ici, elle martèle la haine de Camille pour Rome. L’allitération, elle, répète un <b>son consonne</b>, pas un mot." },
  { q: "« Les sanglots longs / Des violons / De l’automne » (Verlaine). La répétition du son [on] est :", choices: ["une allitération", "une assonance", "une anaphore"], answer: 1, expl: "On répète un <b>son voyelle</b> (ici la voyelle nasale [on] de « longs », « violons ») : c’est une <b>assonance</b>. L’allitération concerne les <b>consonnes</b>. Ce son sourd et long imite la plainte des violons." },
  { q: "« Elle lui raconta tous ses malheurs. » Les paroles sont rapportées au discours :", choices: ["direct", "indirect", "indirect libre", "narrativisé"], answer: 3, expl: "On ne connaît pas les mots prononcés : le narrateur <b>résume</b> simplement l’acte de parole. C’est le discours <b>narrativisé</b>. Il n’y a ni guillemets (direct) ni subordonnée en « que » (indirect)." },
  { q: "Transpose : Il a dit : « J’ai perdu mes clés hier. »", choices: ["Il a dit qu’il a perdu ses clés hier.", "Il a dit qu’il avait perdu ses clés la veille.", "Il a dit qu’il perdait ses clés le lendemain."], answer: 1, expl: "Verbe introducteur au passé : le <b>passé composé devient plus-que-parfait</b> (avait perdu), « je » devient « il », « mes » devient « ses » et <b>hier devient la veille</b>. Piège : oublier de transposer l’indicateur de temps." },
  { q: "Dans <i>Le Petit Chaperon rouge</i>, quel rôle le loup joue-t-il dans le schéma actanciel ?", choices: ["adjuvant", "destinateur", "opposant", "objet"], answer: 2, expl: "Le loup <b>s’oppose</b> à la quête du sujet (le Chaperon, qui doit porter la galette à sa mère-grand) : c’est un <b>opposant</b>. Un adjuvant, au contraire, aide le héros." },
  { q: "« Je te l’ai dit cent fois ! » Nomme la figure de style.", answers: ["hyperbole", "une hyperbole", "l’hyperbole"], expl: "« Cent fois » est une <b>exagération</b> volontaire pour insister : c’est une <b>hyperbole</b>. Ne la confonds pas avec la gradation, qui suppose une suite de termes d’intensité croissante." },
  { q: "Dans un énoncé coupé de la situation d’énonciation (récit), quel temps du passé accompagne habituellement l’imparfait ?", answers: ["passé simple", "le passé simple"], expl: "Le récit repose sur le couple <b>passé simple</b> (actions de premier plan) / imparfait (arrière-plan, description). Le passé composé, lui, appartient au discours, ancré dans la situation d’énonciation." },
  { q: "Au discours indirect introduit par un verbe au passé, en quoi se transforme le futur de l’indicatif ? (nomme le mode ou le temps)", answers: ["conditionnel", "le conditionnel", "conditionnel présent", "le conditionnel présent", "futur dans le passé"], expl: "« Il a dit : “Je viendrai” » devient « Il a dit qu’il <b>viendrait</b> » : le futur devient un <b>conditionnel présent</b>, qui exprime ici le futur vu depuis le passé (on parle aussi de « futur dans le passé »)." },
  { q: "Au discours indirect au passé, par quoi remplace-t-on l’indicateur « maintenant » ?", answers: ["alors", "à ce moment-là", "à ce moment", "à ce moment là"], expl: "« Maintenant » dépend du moment où l’on parle : au discours indirect au passé, il devient <b>alors</b> ou <b>à ce moment-là</b>, comme « demain » devient « le lendemain »." },
  { q: "Dans « Il dit : “Je viendrai.” », comment appelle-t-on le verbe « dit », qui annonce les paroles ? Verbe…", answers: ["introducteur", "verbe introducteur", "de parole", "verbe de parole", "introducteur de parole"], expl: "C’est le <b>verbe introducteur</b> (ou verbe de parole) : dire, demander, répondre, s’écrier… Le varier enrichit un dialogue et donne des indications sur le ton (murmurer, hurler)." },
  { q: "Quel schéma organise les personnages en sujet, objet, destinateur, destinataire, adjuvants et opposants ? Le schéma…", answers: ["actanciel", "schéma actanciel", "le schéma actanciel"], expl: "C’est le <b>schéma actanciel</b>, qui décrit les <b>forces</b> en jeu dans la quête. Ne le confonds pas avec le <b>schéma narratif</b>, qui décrit les <b>étapes</b> du récit (situation initiale, élément perturbateur…)." },
  { type: 'vf', q: "La métaphore utilise un outil de comparaison comme « comme » ou « tel ».", answer: 1, expl: "<b>Faux</b> : c’est la <b>comparaison</b> qui utilise un outil (comme, tel, pareil à). La métaphore rapproche deux réalités <b>sans outil</b> : « Ce lion bondit sur le terrain »." },
  { type: 'vf', q: "Dans le discours indirect libre, les paroles sont introduites par un verbe de parole suivi de « que ».", answer: 1, expl: "<b>Faux</b> : l’indirect libre n’a <b>ni verbe introducteur ni subordination</b>. Il garde seulement les transpositions de l’indirect (3ᵉ personne, temps du récit). « Il dit qu’il viendrait » est de l’indirect tout court." },
  { type: 'vf', q: "Une lettre écrite au présent, avec « je », « tu » et « demain », est un énoncé ancré dans la situation d’énonciation.", answer: 0, expl: "<b>Vrai</b> : « je », « tu » et « demain » ne se comprennent que si l’on connaît <b>qui écrit, à qui et quand</b>. Ce sont les marques d’un énoncé ancré (le discours)." },
  { type: 'vf', q: "Le passé composé est un temps du récit coupé de la situation d’énonciation, au même titre que le passé simple.", answer: 1, expl: "<b>Faux</b> : le passé composé est un temps du <b>discours</b> (énoncé ancré) : il relie l’action passée au moment où l’on parle. Le récit coupé de la situation utilise le <b>passé simple</b> et l’imparfait." }
];

BANK['francais/11'] = [
  { q: "Quel connecteur introduit une <b>cause</b> ?", choices: ["pourtant", "donc", "puisque", "ensuite"], answer: 2, expl: "<b>Puisque</b> introduit une cause (souvent connue de tous). Piège : « donc » introduit la <b>conséquence</b>, c’est-à-dire l’inverse ; « pourtant » oppose et « ensuite » ordonne." },
  { q: "Quel connecteur sert à <b>ajouter</b> un argument ?", choices: ["néanmoins", "en outre", "c’est pourquoi", "car"], answer: 1, expl: "<b>En outre</b> (comme de plus, par ailleurs) ajoute un argument au précédent. « Néanmoins » oppose, « c’est pourquoi » conclut, « car » explique." },
  { q: "« Elle a travaillé régulièrement ; … elle a réussi son examen. » Quel connecteur convient ?", choices: ["cependant", "ainsi", "car"], answer: 1, expl: "La réussite est la <b>conséquence</b> du travail : on emploie <b>ainsi</b>. « Car » inverserait la logique (elle aurait travaillé à cause de sa réussite) et « cependant » marquerait une opposition absurde ici." },
  { q: "Quelle phrase contient un <b>pléonasme</b> à éviter ?", choices: ["Il est sorti tôt.", "Il est sorti dehors.", "Il est sorti en courant."], answer: 1, expl: "On ne peut sortir que <b>dehors</b> : le mot répète une idée déjà contenue dans le verbe. C’est un <b>pléonasme</b>, comme « monter en haut » ou « au jour d’aujourd’hui »." },
  { q: "Quelle phrase est correcte à l’écrit ?", choices: ["On a pas compris la consigne.", "On n’a pas compris la consigne."], answer: 1, expl: "La négation complète exige <b>ne… pas</b>. À l’oral on n’entend pas la différence (la liaison de « on » cache le n’). Astuce : remplace « on » par « il » : « il <b>n’</b>a pas compris »." },
  { q: "Quelle phrase respecte la norme ?", choices: ["Après qu’il soit parti, nous rangeons la salle.", "Après qu’il est parti, nous rangeons la salle."], answer: 1, expl: "<b>Après que</b> se construit avec l’<b>indicatif</b>, car l’action a réellement eu lieu. Piège très fréquent : le subjonctif vient par analogie avec « avant que », qui, lui, exige le subjonctif." },
  { q: "Dans une réponse argumentée, où place-t-on la reformulation du sujet (la problématique) ?", choices: ["dans l’introduction", "au milieu du développement", "uniquement dans la conclusion"], answer: 0, expl: "La problématique se pose dans l’<b>introduction</b>, après l’amorce et avant l’annonce du plan. Le lecteur doit savoir dès le début à quelle question tu réponds." },
  { q: "Le rôle principal de la conclusion est de :", choices: ["introduire un nouvel argument", "recopier l’introduction", "répondre clairement à la question posée"], answer: 2, expl: "La conclusion fait le <b>bilan</b> et <b>répond nettement</b> à la question, éventuellement avec une ouverture. Piège : y glisser un argument nouveau, qui aurait dû être développé plus haut." },
  { q: "Dans la méthode de relecture en 3 passages, quand vérifie-t-on les homophones (a/à, et/est, ces/ses) ?", choices: ["au 1ᵉʳ passage", "au 2ᵉ passage", "au 3ᵉ passage"], answer: 2, expl: "Ordre : 1ᵉʳ passage les <b>verbes</b>, 2ᵉ les <b>groupes nominaux</b>, 3ᵉ les <b>homophones et la ponctuation</b>. Se concentrer sur un seul type d’erreur à la fois rend la relecture bien plus efficace." },
  { q: "Quel est l’ordre conseillé dans un paragraphe argumentatif ?", choices: ["exemple, conclusion, idée", "affirmer l’idée, l’expliquer, l’illustrer, conclure", "conclure, illustrer, affirmer"], answer: 1, expl: "Retiens <b>A-E-I-C</b> : <b>A</b>ffirmer l’idée, l’<b>E</b>xpliquer, l’<b>I</b>llustrer par un exemple précis, <b>C</b>onclure ou relier à la question. L’exemple vient <b>après</b> l’argument qu’il illustre." },
  { q: "Donne un connecteur synonyme de « cependant » qui commence par la lettre n.", answers: ["néanmoins", "neanmoins"], expl: "<b>Néanmoins</b> marque l’opposition, comme cependant, pourtant ou toutefois. Attention à l’orthographe : néan-moins, en un seul mot." },
  { q: "Supprime le pléonasme : réécris « monter en haut » en un seul mot.", answers: ["monter"], expl: "« Monter » contient déjà l’idée d’aller vers le haut : il suffit d’écrire <b>monter</b>. Même chose pour « descendre en bas » ou « prévoir à l’avance »." },
  { q: "Quel mode verbal suit la locution « bien que » ?", answers: ["subjonctif", "le subjonctif"], expl: "<b>Bien que</b> exprime la concession et se construit avec le <b>subjonctif</b> : « bien qu’il <b>soit</b> fatigué ». Piège : écrire « bien qu’il est »." },
  { q: "Combien de minutes le cours conseille-t-il de réserver à la relecture à la fin de chaque partie ?", answers: ["10", "dix"], expl: "Garde <b>10 minutes</b> par partie pour relire : une copie sans fautes rapporte des points, alors que les fautes en coûtent beaucoup au CRPE. Ce temps se prévoit dès le début de l’épreuve." },
  { q: "Complète la célèbre phrase de Descartes avec un connecteur de conséquence : « Je pense, … je suis. »", answers: ["donc"], expl: "<b>Donc</b> introduit la conséquence logique : puisque je pense, j’existe. C’est le connecteur de conséquence le plus simple, à varier avec ainsi, par conséquent, c’est pourquoi." },
  { q: "Relecture : corrige le participe passé dans « Les élèves que j’ai rencontré étaient ravis. »", answers: ["rencontrés"], expl: "Avec l’auxiliaire <b>avoir</b>, le participe s’accorde avec le <b>COD placé avant</b> : « que », mis pour « les élèves » (masculin pluriel), d’où <b>rencontrés</b>. C’est exactement ce que vise le 1ᵉʳ passage de relecture." },
  { type: 'vf', q: "« En effet » introduit une explication ou une justification de ce qui vient d’être dit.", answer: 0, expl: "<b>Vrai</b> : « en effet » annonce la <b>cause</b> ou la preuve de l’affirmation précédente. Piège : on l’emploie à tort comme simple mot de liaison ou pour exprimer une conséquence." },
  { type: 'vf', q: "La conclusion peut se terminer par une ouverture vers une question voisine.", answer: 0, expl: "<b>Vrai</b> : après le bilan qui répond à la question, une <b>ouverture</b> élargit la réflexion. Elle reste facultative : une ouverture artificielle vaut moins qu’une conclusion nette." },
  { type: 'vf', q: "Il faut toujours traiter les questions du sujet dans l’ordre où elles apparaissent.", answer: 1, expl: "<b>Faux</b> : le cours conseille de <b>commencer par la partie où tu es le plus à l’aise</b>, après avoir lu tout le sujet. Numérote bien tes réponses pour que le correcteur s’y retrouve." },
  { type: 'vf', q: "« Ensuite » est un connecteur d’opposition.", answer: 1, expl: "<b>Faux</b> : « ensuite » sert à <b>ordonner</b> les idées (d’abord, ensuite, enfin). Pour opposer, on emploie mais, cependant, pourtant, en revanche." }
];

BANK['francais/f-texte'] = [
  { q: "« Le tonnerre gronda. Tout à coup, la pluie se mit à tomber. » « Tout à coup » est un connecteur :", choices: ["logique", "spatial", "temporel"], answer: 2, expl: "<b>Tout à coup</b> situe un événement dans le <b>temps</b> du récit : c’est un connecteur <b>temporel</b>. Les connecteurs logiques (car, donc, mais) relient des idées, les spatiaux situent dans l’espace." },
  { q: "Lequel de ces connecteurs est <b>spatial</b> ?", choices: ["plus loin", "puis", "donc"], answer: 0, expl: "<b>Plus loin</b> organise l’espace, typiquement dans une <b>description</b>. « Puis » est temporel (récit), « donc » est logique (argumentation)." },
  { q: "« Un chat entra dans la cuisine. Ce chat était tout noir. » La reprise « ce chat » est :", choices: ["pronominale", "nominale fidèle", "nominale infidèle", "une périphrase"], answer: 1, expl: "On reprend <b>le même nom</b> (chat) en changeant seulement le <b>déterminant</b> (un → ce) : c’est une reprise <b>nominale fidèle</b>. Infidèle, ce serait un autre nom (« l’animal », « le matou »)." },
  { q: "« Louis XIV fit bâtir Versailles. Le Roi-Soleil y installa la cour. » « Le Roi-Soleil » est une reprise par :", choices: ["pronom", "périphrase", "nom fidèle"], answer: 1, expl: "On désigne Louis XIV par une <b>expression qui le caractérise</b> au lieu de son nom : c’est une reprise par <b>périphrase</b>. Elle suppose que le lecteur ait la culture pour faire le lien, d’où une difficulté pour les élèves." },
  { q: "« Les roses, les tulipes et les marguerites s’ouvraient. Ces fleurs embaumaient le jardin. » « Ces fleurs » est :", choices: ["un antonyme", "un hyperonyme", "un pronom"], answer: 1, expl: "« Fleur » est le mot <b>générique</b> qui englobe rose, tulipe et marguerite : c’est un <b>hyperonyme</b>, utilisé ici comme reprise nominale infidèle. Le mot plus précis s’appelle un hyponyme." },
  { q: "« Le chat dormait au soleil : ses pattes étaient repliées, sa queue battait doucement, ses oreilles frémissaient. » La progression est :", choices: ["à thème constant", "linéaire", "à thème éclaté"], answer: 2, expl: "Le thème général (le chat) se <b>décompose en sous-thèmes</b> (pattes, queue, oreilles) : c’est une progression <b>à thème éclaté</b>, fréquente dans les portraits et descriptions." },
  { q: "« Hier, j’ai vu un renard. Ce renard boitait. » Dans la 2ᵉ phrase, le <b>propos</b> est :", choices: ["ce renard", "boitait", "hier"], answer: 1, expl: "« Ce renard » est déjà connu : c’est le <b>thème</b>. L’information nouvelle, ce qu’on en dit, est « <b>boitait</b> » : c’est le <b>propos</b>." },
  { q: "« Les rues sont mouillées, … il a plu cette nuit. » Quel connecteur rend la phrase cohérente ?", choices: ["car", "pourtant", "ensuite"], answer: 0, expl: "La pluie <b>explique</b> que les rues soient mouillées : on attend un connecteur de <b>cause</b>, <b>car</b>. « Pourtant » créerait une opposition illogique et « ensuite » une succession qui n’a pas de sens ici." },
  { q: "« Marie a prêté son livre à Julie. Elle était contente. » Pourquoi cette phrase peut-elle gêner un jeune lecteur ?", choices: ["le pronom « elle » peut renvoyer à Marie ou à Julie", "il n’y a aucune reprise", "le connecteur est mal choisi"], answer: 0, expl: "Deux référents féminins précèdent « elle » : le référent est <b>ambigu</b>. Identifier le référent des pronoms est une compétence de compréhension à enseigner explicitement (questions « Qui est “elle” ? », justification par le texte)." },
  { q: "Un élève écrit : « Le loup vit le cochon. Le loup frappa. Le loup souffla. Le loup entra. » Quel est le principal défaut de cohérence ?", choices: ["des répétitions dues à l’absence de reprises variées", "une progression linéaire mal construite", "des connecteurs logiques mal choisis"], answer: 0, expl: "Le même groupe nominal est répété : l’élève ne maîtrise pas encore les <b>reprises</b> (il, l’animal, le prédateur…). Remédiation : chercher ensemble des substituts, puis réécrire. Les connecteurs ne sont pas mal choisis, ils sont absents." },
  { q: "Comment appelle-t-on l’élément (personne, chose) auquel renvoie une reprise ?", answers: ["référent", "le référent", "referent"], expl: "C’est le <b>référent</b>. Dans « Le loup avait faim. Il sortit du bois », le référent de « il » est le loup. Retrouver le référent est la clé de la compréhension des reprises." },
  { q: "« Lucie a trouvé un chaton. Elle le caresse. » Quel est le référent du pronom « le » ?", answers: ["chaton", "le chaton", "un chaton"], expl: "« Le » est masculin singulier et COD de « caresse » : il ne peut reprendre que <b>le chaton</b> (Lucie est reprise par « elle »). Le <b>genre</b> et le <b>nombre</b> du pronom sont de bons indices à faire repérer aux élèves." },
  { q: "Quel type de progression thématique domine dans un récit centré sur un seul personnage ? Progression…", answers: ["à thème constant", "thème constant", "a theme constant", "constante"], expl: "Le personnage reste le <b>thème</b> de phrase en phrase (Marie… Elle… Elle…) : c’est la progression <b>à thème constant</b>, typique du récit. La linéaire domine plutôt dans les descriptions et explications." },
  { q: "Trouve un hyperonyme pour reprendre « le marteau, la scie et le tournevis » (un nom au pluriel).", answers: ["outils", "les outils", "ces outils", "des outils"], expl: "Le mot générique est <b>outils</b> : « Ces outils étaient rangés dans la caisse. » Utiliser un hyperonyme évite la répétition tout en regroupant plusieurs référents." },
  { q: "Les trois outils de la cohérence d’un texte sont les reprises, la progression thématique et les…", answers: ["connecteurs", "les connecteurs"], expl: "Les <b>connecteurs</b> relient les phrases et les idées (temporels, logiques, spatiaux). Avec les reprises (de qui parle-t-on ?) et la progression (qu’apprend-on de nouveau ?), ils font d’une suite de phrases un vrai texte." },
  { q: "Rends la phrase cohérente avec un connecteur de conséquence : « Il faisait très froid, … il mit son manteau. »", answers: ["donc", "alors", "c’est pourquoi", "par conséquent", "ainsi"], expl: "Mettre son manteau est la <b>conséquence</b> du froid : <b>donc</b>, <b>alors</b>, <b>c’est pourquoi</b> conviennent. Piège : « car » inverserait la relation (il ferait froid parce qu’il met son manteau)." },
  { type: 'vf', q: "Le thème d’une phrase coïncide toujours avec son sujet grammatical.", answer: 1, expl: "<b>Faux</b> : dans « Ce livre, je l’ai adoré », le thème est « ce livre » alors que le sujet est « je ». Thème/propos relèvent de l’<b>information</b>, sujet/verbe de la <b>syntaxe</b> : ce sont deux analyses différentes." },
  { type: 'vf', q: "La progression linéaire est fréquente dans les textes descriptifs et explicatifs.", answer: 0, expl: "<b>Vrai</b> : chaque nouvelle information devient le point de départ de la phrase suivante (une maison → ce jardin → les arbres…), ce qui permet d’enchaîner et d’approfondir." },
  { type: 'vf', q: "« Mais », « donc » et « car » sont des connecteurs temporels.", answer: 1, expl: "<b>Faux</b> : ce sont des connecteurs <b>logiques</b> (opposition, conséquence, cause), propres à l’argumentation. Les temporels sont « d’abord, puis, le lendemain, tout à coup »." },
  { type: 'vf', q: "Reprendre toujours un personnage par le même nom rend un texte plus cohérent et mieux écrit.", answer: 1, expl: "<b>Faux</b> : la répétition systématique alourdit le texte. On varie les reprises (pronoms, synonymes, hyperonymes, périphrases), en veillant à ce que le référent reste toujours identifiable." }
];

BANK['francais/f-impersonnels'] = [
  { q: "« Des propos très (provoquer) » :", choices: ["provoquants", "provocants", "provoquant"], answer: 1, expl: "« Très » montre une <b>qualité</b> : c’est l’<b>adjectif verbal</b>, qui s’écrit <b>provocant</b> (avec c) et s’accorde : des propos provocants. Le participe présent « provoquant » garde le qu et reste invariable." },
  { q: "« Ces deux méthodes sont (équivaloir). »", choices: ["équivalantes", "équivalant", "équivalentes"], answer: 2, expl: "Attribut du sujet, le mot exprime une <b>qualité</b> : c’est l’<b>adjectif verbal équivalent</b> (en -ent), accordé au féminin pluriel : <b>équivalentes</b>. Le participe présent s’écrit « équivalant » (en équivalant à…)." },
  { q: "« Les voyageurs, (différer) leur départ, restèrent à l’hôtel. »", choices: ["différant", "différents", "différent"], answer: 0, expl: "Le mot exprime une <b>action</b> et a un <b>complément</b> (leur départ) : c’est le participe présent <b>différant</b>, invariable. L’adjectif « différent » signifie « pas pareil »." },
  { q: "« Elle a appris l’anglais en regardant des séries. » Le gérondif exprime :", choices: ["le moyen", "la cause", "l’opposition"], answer: 0, expl: "Regarder des séries est <b>le moyen</b> par lequel elle a appris : on peut répondre à la question « comment ? / par quel moyen ? ». Pour la cause, on se demanderait « pourquoi ? »." },
  { q: "« Il est entré en sifflant. » Le gérondif exprime :", choices: ["la condition", "la manière", "la cause"], answer: 1, expl: "Le gérondif dit <b>de quelle manière</b> il est entré (en sifflant = d’un air léger). Pour la condition, on aurait « En travaillant, tu réussiras » (= si tu travailles)." },
  { q: "Quelle phrase contient une <b>faute</b> d’emploi du gérondif ?", choices: ["En entrant dans la classe, les élèves se taisent.", "En sortant de l’école, le car m’a ramené.", "En lisant, on apprend."], answer: 1, expl: "Le sujet du gérondif doit être <b>celui du verbe principal</b>. Ici, le sujet de « a ramené » est « le car », mais ce n’est pas le car qui sort de l’école ! Correction : « Quand je suis sorti de l’école, le car m’a ramené »." },
  { q: "Quelle est la forme de l’infinitif passé de « finir » ?", choices: ["finissant", "avoir fini", "ayant fini", "en finissant"], answer: 1, expl: "L’infinitif passé se forme avec l’<b>auxiliaire à l’infinitif + participe passé</b> : avoir fini. « Ayant fini » est le participe passé composé et « en finissant » un gérondif." },
  { q: "« Ayant terminé son travail, il sortit. » « Ayant terminé » est :", choices: ["un gérondif", "un infinitif passé", "la forme composée du participe (participe passé composé)"], answer: 2, expl: "<b>Ayant</b> (participe présent de l’auxiliaire) + participe passé donne la <b>forme composée du participe</b>, qui marque l’antériorité. Il n’y a pas de « en », donc ce n’est pas un gérondif." },
  { q: "Quelle phrase contient une <b>proposition infinitive</b> ?", choices: ["Je veux partir.", "Je regarde les nuages passer.", "Il faut manger."], answer: 1, expl: "Dans « Je regarde les nuages passer », l’infinitif « passer » a son <b>propre sujet</b> (les nuages), après un verbe de perception. Dans « Je veux partir », c’est « je » qui part : l’infinitif n’a pas de sujet propre, ce n’est pas une infinitive." },
  { q: "Quelle phrase contient une <b>proposition participiale</b> ?", choices: ["Terminant son travail, Paul sourit.", "En terminant son travail, Paul sourit.", "Le travail terminé, nous partîmes en récréation."], answer: 2, expl: "Dans « Le travail terminé », le participe a son <b>propre sujet</b> (le travail), différent de celui de la principale (nous) : c’est une participiale. Dans les deux autres phrases, le sujet du participe et du gérondif est Paul, celui du verbe principal." },
  { q: "Complète avec l’adjectif verbal de « communiquer » : « des vases … »", answers: ["communicants"], expl: "L’adjectif verbal s’écrit avec <b>c</b> : <b>communicant</b>, accordé ici au masculin pluriel : des vases communicants. Le participe présent s’écrit « communiquant » (en communiquant avec…)." },
  { q: "Écris le participe présent du verbe « fatiguer ».", answers: ["fatiguant"], expl: "Le participe présent garde le radical du verbe : <b>fatiguant</b> (avec u), comme dans « en fatiguant ses adversaires ». C’est l’adjectif, lui, qui perd le u : un travail fatigant." },
  { q: "Le gérondif se forme avec quelle préposition placée devant le participe présent ?", answers: ["en"], expl: "Gérondif = <b>en</b> + participe présent : en chantant, en lisant. Sans « en », on a un simple participe présent." },
  { q: "Complète avec l’adjectif verbal de « exceller » : « C’est une élève … ».", answers: ["excellente"], expl: "L’adjectif s’écrit en <b>-ent</b> : <b>excellent</b>, accordé ici au féminin : excellente. Le participe présent s’écrit « excellant » (excellant en mathématiques, elle…), comme précédant / précédent." },
  { q: "Écris l’infinitif passé du verbe « partir » (au masculin).", answers: ["être parti", "etre parti"], expl: "« Partir » se conjugue avec l’auxiliaire <b>être</b> : l’infinitif passé est donc <b>être parti</b> (« après être parti tôt, il arriva le premier »). Piège : « avoir parti » n’existe pas." },
  { q: "« Sachant » est le participe présent de quel verbe ?", answers: ["savoir"], expl: "<b>Sachant</b> vient de <b>savoir</b>, et son adjectif verbal est différent : <b>savant</b> (un chien savant). Les participes présents irréguliers (ayant, étant, sachant) sont à connaître." },
  { type: 'vf', q: "Le participe présent s’accorde en genre et en nombre avec le nom auquel il se rapporte.", answer: 1, expl: "<b>Faux</b> : le participe présent est <b>invariable</b> (des enfants obéissant à leurs parents). C’est l’<b>adjectif verbal</b> qui s’accorde (des enfants obéissants)." },
  { type: 'vf', q: "Le participe présent ne peut jamais avoir de complément.", answer: 1, expl: "<b>Faux</b> : c’est même un indice pour le reconnaître ! Le participe présent exprime une action et peut avoir un <b>complément</b> (fatiguant <u>ses élèves</u>) ou être précédé de « ne »." },
  { type: 'vf', q: "« Négligeant » et « négligent » se prononcent de la même façon.", answer: 0, expl: "<b>Vrai</b> : les deux se prononcent [négligeant], c’est pourquoi on ne peut pas se fier à l’oreille. Il faut se demander s’il s’agit d’une <b>action</b> (participe : négligeant) ou d’une <b>qualité</b> (adjectif : négligent)." },
  { type: 'vf', q: "Dans « Elle travaille en écoutant de la musique », le sujet du gérondif est « elle ».", answer: 0, expl: "<b>Vrai</b> : le gérondif n’a pas de sujet exprimé, il prend <b>celui du verbe principal</b>, ici « elle ». C’est elle qui travaille et qui écoute : la phrase est correcte." }
];

BANK['francais/f-poesie'] = [
  { q: "Rimes de schéma ABAB :", choices: ["plates", "croisées", "embrassées"], answer: 1, expl: "En <b>ABAB</b>, les rimes alternent et se croisent : rimes <b>croisées</b>. Repère : AABB plates (suivies), ABBA embrassées (B entouré par A)." },
  { q: "Une strophe de 4 vers s’appelle :", choices: ["un distique", "un tercet", "un quatrain", "un quintil"], answer: 2, expl: "4 vers = un <b>quatrain</b> (comme « quatre »). Distique = 2, tercet = 3, quintil = 5. Le sonnet commence par deux quatrains." },
  { q: "La pause qui partage l’alexandrin classique en deux moitiés s’appelle :", choices: ["l’enjambement", "la césure", "la diérèse"], answer: 1, expl: "La <b>césure</b> est la pause au milieu de l’alexandrin (après la 6ᵉ syllabe). L’enjambement, lui, est le débordement de la phrase sur le vers suivant." },
  { q: "« Sous le pont Mirabeau coule la Seine » (Apollinaire) est :", choices: ["un octosyllabe", "un décasyllabe", "un alexandrin"], answer: 1, expl: "Sous / le / pont / Mi / ra / beau / cou / le / la / Seine = <b>10 syllabes</b> : un <b>décasyllabe</b>. Le e de « coule » se prononce car il est suivi d’une consonne (la) ; celui de « Seine », en fin de vers, ne compte pas." },
  { q: "La rime « bonté / été » est :", choices: ["pauvre", "suffisante", "riche"], answer: 1, expl: "On compte les sons communs depuis la fin : [t] + [é] = <b>2 sons</b>, donc rime <b>suffisante</b>. On compte des <b>sons</b>, pas des lettres." },
  { q: "La rime « charmant / dormant » est :", choices: ["pauvre", "suffisante", "riche"], answer: 2, expl: "Sons communs : [r] + [m] + [an] = <b>3 sons</b> : rime <b>riche</b>. Ensuite les voyelles diffèrent (char- / dor-), on s’arrête là." },
  { q: "La rime « fleur / douleur » est :", choices: ["féminine, car « fleur » et « douleur » sont des noms féminins", "masculine, car elle ne se termine pas par un e muet"], answer: 1, expl: "Le genre de la rime ne dépend <b>pas du genre du nom</b> mais de la terminaison : sans e muet final, la rime est <b>masculine</b>. Piège classique, à l’inverse « un rêve / se lève » donne une rime féminine." },
  { q: "Qui a écrit les fables <i>Le Corbeau et le Renard</i> et <i>La Cigale et la Fourmi</i> (1668) ?", choices: ["Charles Perrault", "Jean de La Fontaine", "Jacques Prévert"], answer: 1, expl: "<b>Jean de La Fontaine</b> publie ses premières <i>Fables</i> en 1668, au XVIIᵉ siècle : récits en vers avec une <b>morale</b>, souvent inspirés d’Ésope. Perrault, à la même époque, écrit des contes." },
  { q: "Lequel de ces recueils est composé de <b>poèmes en prose</b> ?", choices: ["<i>Les Contemplations</i> (Hugo)", "<i>Les Fables</i> (La Fontaine)", "<i>Le Spleen de Paris</i> (Baudelaire)"], answer: 2, expl: "<i>Le Spleen de Paris</i> (ou <i>Petits poèmes en prose</i>) de <b>Baudelaire</b> fonde le poème en prose : pas de vers, mais un travail sur le rythme et les images. Hugo et La Fontaine écrivent en vers." },
  { q: "À l’école, faire mémoriser et dire un poème vise surtout à :", choices: ["travailler l’oral, l’interprétation et la mise en voix", "apprendre l’orthographe des mots du poème", "occuper les élèves en fin de journée"], answer: 0, expl: "Dire un poème, c’est l’<b>interpréter</b> : rythme, pauses, intonation traduisent une compréhension du texte. C’est un vrai travail de l’<b>oral</b>, qu’on prépare et qu’on évalue avec des critères." },
  { q: "Combien de syllabes compte ce vers de Hugo : « Demain, dès l’aube, à l’heure où blanchit la campagne » ?", answers: ["12", "douze"], expl: "De / main / dès / l’au / be‿à / l’heu / re‿où / blan / chit / la / cam / pagne = <b>12</b>. Les e de « aube » et « heure » s’élident devant une voyelle ; celui de « campagne », en fin de vers, ne compte pas : c’est un alexandrin." },
  { q: "Comment s’appelle chacune des deux moitiés d’un alexandrin séparées par la césure ?", answers: ["hémistiche", "un hémistiche", "hemistiche", "les hémistiches"], expl: "Chaque moitié est un <b>hémistiche</b> (du grec « demi-vers ») : dans l’alexandrin classique, 6 + 6 syllabes. Le h et l’accent sont à retenir pour l’orthographe." },
  { q: "Comment s’appelle un poème dont les premières lettres des vers, lues de haut en bas, forment un mot ?", answers: ["acrostiche", "un acrostiche"], expl: "C’est un <b>acrostiche</b>, jeu poétique très utilisé en classe (avec le prénom de l’élève par exemple) : il donne une contrainte simple qui aide à entrer dans l’écriture." },
  { q: "Combien de syllabes compte le mot « passion » prononcé avec une diérèse ?", answers: ["3", "trois"], expl: "Avec diérèse, on sépare [i] et [on] : pa / ssi / on = <b>3 syllabes</b>. Prononcé normalement (synérèse, pa-ssion), il n’en a que 2. La diérèse met souvent le mot en valeur." },
  { q: "Combien de syllabes compte le 2ᵉ vers d’un haïku traditionnel ?", answers: ["7", "sept"], expl: "Le haïku traditionnel suit le schéma <b>5-7-5</b> : le vers central est le plus long, avec <b>7</b> syllabes. En français, on respecte souvent cette contrainte de façon souple." },
  { q: "Comment appelle-t-on une strophe de 2 vers ?", answers: ["distique", "un distique"], expl: "Une strophe de <b>2 vers</b> est un <b>distique</b>. Ordre à retenir : distique (2), tercet (3), quatrain (4), quintil (5), sizain (6)." },
  { type: 'vf', q: "Dans le vers libre, la rime est obligatoire.", answer: 1, expl: "<b>Faux</b> : le vers libre n’a <b>ni mètre régulier ni rime obligatoire</b> (Apollinaire, Prévert). Le rythme repose alors sur les retours à la ligne, les répétitions, les sonorités." },
  { type: 'vf', q: "Le e muet placé en fin de vers ne se compte pas comme une syllabe.", answer: 0, expl: "<b>Vrai</b> : en fin de vers, le e muet ne se prononce pas et ne compte pas (« campa-gne » compte pour « cam-pagne », 2 syllabes). Il détermine en revanche le genre de la rime : féminine." },
  { type: 'vf', q: "Dans le vers « Une âme se réveille », le e de « Une » forme une syllabe.", answer: 1, expl: "<b>Faux</b> : le e de « Une » est suivi d’une voyelle (âme) : il s’<b>élide</b>, on prononce « u-nâ-me ». Il ne compte que devant une consonne." },
  { type: 'vf', q: "Un sonnet se compose de deux tercets suivis de deux quatrains.", answer: 1, expl: "<b>Faux</b> : c’est l’inverse. Le sonnet commence par <b>deux quatrains</b> et se termine par <b>deux tercets</b>, soit 4 + 4 + 3 + 3 = 14 vers. Le dernier vers (la chute) est souvent mis en valeur." }
];

BANK['francais/f-litterature'] = [
  { q: "Auteur de <i>Matilda</i> :", choices: ["Daniel Pennac", "Roald Dahl", "Pierre Gripari"], answer: 1, expl: "<i>Matilda</i> (1988) est un roman de <b>Roald Dahl</b>, auteur britannique aussi de <i>Charlie et la chocolaterie</i>. Son humour et ses adultes terribles plaisent beaucoup au cycle 3." },
  { q: "Auteur de l’album <i>Petit-Bleu et Petit-Jaune</i> :", choices: ["Maurice Sendak", "Mario Ramos", "Leo Lionni"], answer: 2, expl: "<b>Leo Lionni</b> publie <i>Petit-Bleu et Petit-Jaune</i> en 1959 : deux taches de couleur qui se mélangent et deviennent vertes. Album très utilisé en cycle 1." },
  { q: "Quand l’image apporte des informations que le texte ne donne pas, le rapport texte-image est de :", choices: ["redondance", "complémentarité", "disjonction"], answer: 1, expl: "L’image <b>ajoute</b> du sens au texte : c’est la <b>complémentarité</b>. Redondance = l’image répète le texte ; disjonction = elle le contredit." },
  { q: "Voltaire appartient au mouvement :", choices: ["des Lumières", "du romantisme", "de la Pléiade"], answer: 0, expl: "<b>Voltaire</b> (1694-1778) est une grande figure des <b>Lumières</b> (XVIIIᵉ siècle), qui défendent la raison et la tolérance (<i>Candide</i>). Piège : la Pléiade, c’est le XVIᵉ siècle." },
  { q: "Ronsard et Du Bellay appartiennent à :", choices: ["la Pléiade (XVIᵉ siècle)", "le classicisme (XVIIᵉ siècle)", "le surréalisme (XXᵉ siècle)"], answer: 0, expl: "<b>Ronsard</b> et <b>Du Bellay</b> forment le cœur de la <b>Pléiade</b>, groupe de poètes de la Renaissance (XVIᵉ siècle) qui veulent enrichir la langue française." },
  { q: "Verlaine et Rimbaud sont rattachés au :", choices: ["classicisme", "symbolisme", "naturalisme"], answer: 1, expl: "<b>Verlaine</b> et <b>Rimbaud</b> sont associés au <b>symbolisme</b> (fin du XIXᵉ siècle), poésie de la suggestion et de la musicalité. Le naturalisme, c’est Zola, en roman." },
  { q: "Ionesco (<i>La Cantatrice chauve</i>) est un auteur du :", choices: ["théâtre de l’absurde", "romantisme", "classicisme"], answer: 0, expl: "<b>Ionesco</b>, comme Beckett, illustre le <b>théâtre de l’absurde</b> (années 1950) : dialogues vides, logique déréglée, pour montrer l’absurdité de la condition humaine." },
  { q: "Les <b>pages de garde</b> d’un album sont :", choices: ["le résumé imprimé au dos du livre", "les pages collées à l’intérieur de la couverture, au début et à la fin", "la page où figurent le titre et l’éditeur"], answer: 1, expl: "Les <b>pages de garde</b> relient la couverture au cahier de pages, au début et à la fin. Dans beaucoup d’albums, elles sont illustrées et annoncent l’histoire : on les fait observer aux élèves. Le résumé au dos, c’est la 4ᵉ de couverture." },
  { q: "Auteurs du <i>Gruffalo</i> :", choices: ["Goscinny et Sempé", "Julia Donaldson et Axel Scheffler", "les frères Grimm"], answer: 1, expl: "<i>Le Gruffalo</i> (1999) est écrit par <b>Julia Donaldson</b> et illustré par <b>Axel Scheffler</b> : une souris rusée invente un monstre pour effrayer ses prédateurs. Goscinny et Sempé, c’est <i>Le Petit Nicolas</i>." },
  { q: "Dans les fonctions de Propp, le moment où le héros désobéit à un interdit s’appelle :", choices: ["l’épreuve", "le départ", "la transgression"], answer: 2, expl: "Après l’<b>interdiction</b> vient la <b>transgression</b> : le Petit Chaperon rouge parle au loup, alors qu’elle ne devrait pas. Ces fonctions s’enchaînent dans un ordre récurrent." },
  { q: "Qui a écrit <i>Le Petit Prince</i> ?", answers: ["Saint-Exupéry", "Antoine de Saint-Exupéry", "Saint-Exupery", "Saint Exupéry", "Antoine de Saint Exupéry"], expl: "<i>Le Petit Prince</i> (1943) est d’<b>Antoine de Saint-Exupéry</b>, aviateur et écrivain, qui l’a aussi illustré. C’est une œuvre de référence pour le cycle 3." },
  { q: "Qui a écrit <i>Les Contes de la rue Broca</i> ?", answers: ["Gripari", "Pierre Gripari"], expl: "<b>Pierre Gripari</b> publie <i>Les Contes de la rue Broca</i> en 1967 (dont <i>La Sorcière de la rue Mouffetard</i>) : des contes merveilleux installés dans le Paris moderne, pleins d’humour." },
  { q: "Quelle formule ouvre traditionnellement le conte merveilleux ?", answers: ["il était une fois", "il etait une fois"], expl: "<b>Il était une fois</b> installe la situation initiale dans un temps <b>indéterminé</b>, hors du réel : c’est le signal du conte. Les élèves peuvent le comparer avec d’autres ouvertures (« Autrefois… »)." },
  { q: "À quel siècle se situent les Lumières ? (écris le siècle)", answers: ["XVIIIe", "XVIIIᵉ", "XVIII", "18e", "18", "18ème", "XVIIIème", "18ᵉ", "dix-huitième"], expl: "Les Lumières, c’est le <b>XVIIIᵉ siècle</b> (années 1700) : Voltaire, Montesquieu, Diderot, Rousseau, l’<i>Encyclopédie</i>. Rappel : le XVIIIᵉ siècle va de 1701 à 1800." },
  { q: "Le dos du livre, où figure souvent un résumé, s’appelle la … de couverture (écris le mot ou le nombre).", answers: ["4e", "4ᵉ", "quatrième", "4ème", "quatrieme", "4"], expl: "C’est la <b>4ᵉ de couverture</b>. Elle sert à faire des <b>hypothèses de lecture</b> avant de lire l’album, une activité classique en classe." },
  { q: "Qui est le chef de file du surréalisme (auteur du <i>Manifeste du surréalisme</i>, 1924) ?", answers: ["Breton", "André Breton", "Andre Breton"], expl: "<b>André Breton</b> publie le <i>Manifeste du surréalisme</i> en 1924 : libérer l’imagination, le rêve, l’inconscient (écriture automatique). Éluard est l’un de ses compagnons." },
  { type: 'vf', q: "Le ministère publie sur Éduscol des listes de référence d’œuvres de littérature de jeunesse pour les différents cycles.", answer: 0, expl: "<b>Vrai</b> : ces listes aident l’enseignant à choisir des œuvres variées et à construire une <b>culture littéraire commune</b> tout au long de la scolarité." },
  { type: 'vf', q: "<i>Charlie et la chocolaterie</i> est un roman de Daniel Pennac.", answer: 1, expl: "<b>Faux</b> : c’est un roman de <b>Roald Dahl</b> (1964). Daniel Pennac a écrit <i>L’Œil du loup</i> et <i>Kamo</i>." },
  { type: 'vf', q: "Montaigne est un auteur humaniste du XVIᵉ siècle.", answer: 0, expl: "<b>Vrai</b> : Montaigne (1533-1592) écrit les <i>Essais</i>, réflexion sur l’homme typique de l’<b>humanisme</b> de la Renaissance, comme Rabelais." },
  { type: 'vf', q: "Dans un album, il y a redondance quand l’image contredit le texte.", answer: 1, expl: "<b>Faux</b> : la <b>redondance</b>, c’est quand l’image <b>répète</b> le texte. Quand elle le contredit, on parle de <b>disjonction</b>, souvent source d’humour." }
];

BANK['francais/f-didactique'] = [
  { q: "Le modèle de la « simple view of reading » est dû à :", choices: ["Piaget et Vygotski", "Gough et Tunmer", "Vladimir Propp"], answer: 1, expl: "Ce modèle (1986) est celui de <b>Gough et Tunmer</b> : lecture = décodage × compréhension. Piaget et Vygotski sont des psychologues du développement ; Propp a étudié les contes." },
  { q: "Laquelle de ces activités travaille la <b>conscience phonologique</b> ?", choices: ["copier une phrase", "frapper les syllabes d’un mot", "colorier un dessin"], answer: 1, expl: "La conscience phonologique, c’est manipuler les <b>sons</b> de la langue orale (syllabes, rimes, phonèmes) : frapper les syllabes en est un exercice typique, dès la maternelle. Copier relève du geste d’écriture." },
  { q: "Un élève décode parfaitement mais ne sait pas dire de quoi parle le texte. D’après la « simple view of reading » :", choices: ["il sait lire, il n’y a pas de problème", "sa lecture reste défaillante : il faut travailler la compréhension", "il faut reprendre uniquement le code"], answer: 1, expl: "Lecture = décodage × compréhension : si la compréhension est faible, le produit l’est aussi. Il faut <b>enseigner explicitement</b> des stratégies de compréhension (reformuler, inférer, se faire un film)." },
  { q: "« Tom souffla les huit bougies de son gâteau. » Quelle inférence peut faire le lecteur ?", choices: ["Tom fête ses huit ans", "Tom aime le chocolat", "Tom est malade"], answer: 0, expl: "Rien n’est dit explicitement, mais les <b>indices</b> (huit bougies, gâteau) et nos <b>connaissances</b> du monde permettent de déduire l’anniversaire : c’est une <b>inférence</b>. Les autres réponses ne s’appuient sur aucun indice." },
  { q: "Quel ordre suit la démarche de production d’écrit ?", choices: ["mettre en texte → planifier → publier → réviser", "planifier → mettre en texte → réviser → publier", "réviser → planifier → mettre en texte → publier"], answer: 1, expl: "On <b>planifie</b> (idées, plan), on <b>met en texte</b>, on <b>révise</b> (relire avec une grille, améliorer), puis on <b>publie</b>. La révision vient après le premier jet : impossible de réviser un texte qui n’existe pas." },
  { q: "En maternelle, la <b>dictée à l’adulte</b> permet surtout à l’enfant de :", choices: ["composer un texte à l’oral que l’adulte écrit, sans être bloqué par le geste d’écriture", "apprendre à tracer les lettres cursives", "être évalué en orthographe"], answer: 0, expl: "L’enfant <b>compose</b> un texte et découvre qu’on ne dit pas un écrit comme on parle (l’adulte écrit lentement, fait reformuler). Il entre ainsi dans la langue écrite avant de savoir écrire seul." },
  { q: "La fluence est souvent évaluée par :", choices: ["une dictée de mots", "un questionnaire de compréhension", "le nombre de mots correctement lus en une minute"], answer: 2, expl: "On mesure le nombre de <b>mots correctement lus par minute</b> (MCLM), qui combine vitesse et exactitude ; on observe aussi l’expressivité. La compréhension s’évalue à part." },
  { q: "Un élève de CP lit « lavabo » au lieu de « lavoir » en s’appuyant sur le début du mot. Que montre cette erreur ?", choices: ["il fait une inférence pertinente", "il devine à partir d’indices partiels au lieu de décoder tout le mot", "il a une très bonne fluence"], answer: 1, expl: "Il identifie le début (la-v…) puis <b>devine</b> un mot connu : le décodage n’est pas mené jusqu’au bout. Remédiation : décoder syllabe par syllabe (la-voir), puis vérifier que le mot lu correspond au sens." },
  { q: "« Raconte avec tes mots ce que tu as compris de l’histoire. » Cette activité s’appelle :", choices: ["la dictée négociée", "le rappel de récit", "la fluence"], answer: 1, expl: "Le <b>rappel de récit</b> oblige à <b>reformuler</b> et à remettre les événements dans l’ordre : il montre ce que l’élève a réellement compris, au-delà de la simple restitution de phrases." },
  { q: "Dans les programmes, l’oral est :", choices: ["seulement un moyen d’apprendre dans les autres disciplines", "un domaine réservé à la maternelle", "à la fois un moyen d’apprendre et un objet d’enseignement"], answer: 2, expl: "On apprend <b>par</b> l’oral (échanges, explications) et on apprend <b>l’</b>oral (écouter, dire, débattre, exposer), avec des objectifs et des critères précis, à tous les cycles." },
  { q: "Quel sigle désigne les correspondances graphèmes-phonèmes ?", answers: ["CGP", "C.G.P."], expl: "<b>CGP</b> : correspondances graphèmes-phonèmes, par exemple le graphème « ch » correspond au phonème [ch]. Leur enseignement explicite et progressif est le cœur de l’apprentissage du code au CP." },
  { q: "Combien de phonèmes compte le mot « chapeau » ?", answers: ["4", "quatre"], expl: "On entend [ch] [a] [p] [o] : <b>4 phonèmes</b>. Piège : compter les lettres (7). « ch » et « eau » sont des graphèmes de plusieurs lettres qui notent un seul son." },
  { q: "Combien de graphèmes compte le mot « oiseau » ?", answers: ["3", "trois"], expl: "On découpe en <b>oi</b> / <b>s</b> / <b>eau</b> : <b>3 graphèmes</b>. Attention, « oi » note deux phonèmes [w] + [a], donc le mot a 4 phonèmes mais 3 graphèmes." },
  { q: "Combien de syllabes orales compte le mot « éléphant » ?", answers: ["3", "trois"], expl: "é / lé / phant : <b>3 syllabes</b> orales. On les frappe dans les mains en maternelle. Le « ph » note le son [f] et « an » une seule voyelle nasale." },
  { q: "Comment s’appelle la dictée dont les élèves ont étudié à l’avance les mots et les difficultés ? La dictée…", answers: ["préparée", "dictée préparée", "preparee", "la dictée préparée"], expl: "La <b>dictée préparée</b> fait travailler le texte avant (observation, mémorisation des mots difficiles) : la dictée devient un moment d’<b>apprentissage</b> et pas seulement de contrôle." },
  { q: "Dans la fluence, comment s’appelle la composante expressive de la lecture (intonation, respect de la ponctuation) ?", answers: ["prosodie", "la prosodie"], expl: "La <b>prosodie</b> est l’expressivité de la lecture : pauses, intonation, groupes de souffle. Elle montre que l’élève comprend ce qu’il lit, en plus de l’exactitude et de la vitesse." },
  { type: 'vf', q: "La compréhension se développe toute seule dès que l’élève sait décoder.", answer: 1, expl: "<b>Faux</b> : comprendre <b>s’enseigne</b>. Il faut travailler explicitement les stratégies (inférences, reprises, reformulation, représentation mentale), même chez les bons décodeurs." },
  { type: 'vf', q: "La lecture à voix haute par l’enseignant reste utile même quand les élèves savent lire seuls.", answer: 0, expl: "<b>Vrai</b> : elle donne accès à des textes plus <b>complexes</b> que ceux que les élèves liraient seuls et offre un modèle de lecture expressive. C’est un apprentissage à part entière, à tous les cycles." },
  { type: 'vf', q: "Au CP, il est recommandé de faire mémoriser globalement beaucoup de mots avant d’enseigner le code.", answer: 1, expl: "<b>Faux</b> : on enseigne le <b>code</b> de façon explicite et syllabique dès le début, avec des textes déchiffrables. La mémorisation de quelques mots outils fréquents complète ce travail, elle ne le remplace pas." },
  { type: 'vf', q: "Classer des mots par catégories (fruits, outils, moyens de transport) aide à structurer le vocabulaire.", answer: 0, expl: "<b>Vrai</b> : la <b>catégorisation</b> organise le lexique en mémoire, comme les familles de mots. Elle complète l’apprentissage en contexte et le réemploi fréquent." }
];

BANK['francais/f-c4-themes'] = [
  { q: "Le registre dominant d’une comédie de Molière comme <i>Le Médecin malgré lui</i> est :", choices: ["tragique", "comique", "lyrique"], answer: 1, expl: "La comédie cherche à faire <b>rire</b> (quiproquos, coups de bâton, jeux de mots) : registre <b>comique</b>. Chez Molière, le rire sert souvent aussi à critiquer, d’où un registre satirique associé." },
  { q: "Lequel de ces auteurs a écrit des <b>tragédies</b> classiques ?", choices: ["Maupassant", "Racine", "Philippe Lejeune"], answer: 1, expl: "<b>Racine</b> (<i>Phèdre</i>, <i>Andromaque</i>) est le grand auteur de tragédies du XVIIᵉ siècle. Maupassant écrit des nouvelles et Lejeune est un critique qui a théorisé l’autobiographie." },
  { q: "Les <i>Confessions</i>, où Rousseau raconte sa propre vie, relèvent de la grande entrée :", choices: ["Se chercher, se construire", "Agir sur le monde", "Regarder le monde, inventer des mondes"], answer: 0, expl: "Raconter sa vie, c’est « <b>se raconter, se représenter</b> », questionnement de la grande entrée <b>Se chercher, se construire</b>. Rousseau y fonde l’autobiographie moderne." },
  { q: "Une fable de La Fontaine qui se moque des puissants (<i>Les Animaux malades de la peste</i>) relève de la grande entrée :", choices: ["Regarder le monde, inventer des mondes", "Se chercher, se construire", "Vivre en société, participer à la société"], answer: 2, expl: "Dénoncer les <b>travers de la société</b> (fable, satire, conte philosophique) est un questionnement de <b>Vivre en société, participer à la société</b>. La fable critique ici l’injustice des puissants." },
  { q: "Le questionnement « Héros et héroïsmes » appartient à la grande entrée :", choices: ["Agir sur le monde", "Se chercher, se construire", "Vivre en société, participer à la société"], answer: 0, expl: "Le héros <b>agit</b> : « Héros et héroïsmes » relève d’<b>Agir sur le monde</b>, comme « informer, s’informer, déformer » et la littérature engagée." },
  { q: "Le registre d’un texte qui attaque vivement un adversaire, comme <i>J’accuse… !</i> de Zola, est :", choices: ["lyrique", "fantastique", "polémique"], answer: 2, expl: "Le registre <b>polémique</b> (du grec polemos, la guerre) attaque avec violence une personne ou une idée. Zola y accuse l’état-major dans l’affaire Dreyfus." },
  { q: "Une fée transforme une citrouille en carrosse et personne ne s’en étonne. On est dans :", choices: ["le merveilleux", "le fantastique", "le réalisme"], answer: 0, expl: "Le surnaturel est <b>accepté d’emblée</b>, sans hésitation : c’est le <b>merveilleux</b> du conte. Le fantastique, lui, repose sur le <b>doute</b> entre explication rationnelle et surnaturelle." },
  { q: "Lors de la première lecture d’un texte à l’écrit 1, l’objectif est surtout de :", choices: ["comprendre l’histoire dans sa globalité", "relever toutes les figures de style", "corriger l’orthographe"], answer: 0, expl: "La 1ʳᵉ lecture sert à <b>comprendre l’ensemble</b> (qui, quoi, où, quand). C’est la 2ᵉ lecture, crayon en main, qui sert à repérer champs lexicaux, figures et procédés." },
  { q: "Valeur du présent dans « La Terre tourne autour du Soleil » :", choices: ["présent de vérité générale", "présent de narration", "présent d’énonciation"], answer: 0, expl: "L’énoncé est <b>vrai en tout temps</b> : c’est un présent de <b>vérité générale</b>, comme dans les morales de fables. Le présent de narration raconte un fait passé au présent pour le rendre vivant." },
  { q: "Valeur de l’imparfait dans « Chaque matin, il se levait à six heures » :", choices: ["action ponctuelle", "habitude (valeur itérative)", "futur dans le passé"], answer: 1, expl: "« Chaque matin » montre une action <b>répétée</b> : c’est l’imparfait d’<b>habitude</b> (itératif). Une action ponctuelle de premier plan serait au passé simple." },
  { q: "Quel critique a défini le « pacte autobiographique » ?", answers: ["Lejeune", "Philippe Lejeune"], expl: "<b>Philippe Lejeune</b> (<i>Le Pacte autobiographique</i>, 1975) : l’auteur s’engage à dire la vérité sur sa vie, avec <b>auteur = narrateur = personnage principal</b>." },
  { q: "Quel registre montre un personnage écrasé par un destin auquel il ne peut échapper ?", answers: ["tragique", "le tragique"], expl: "Le registre <b>tragique</b> met en scène la <b>fatalité</b> : le héros lutte mais court à sa perte (Phèdre chez Racine). Ne le confonds pas avec le pathétique, qui cherche surtout à émouvoir." },
  { q: "Quel auteur a écrit la nouvelle fantastique <i>Le Horla</i> ?", answers: ["Maupassant", "Guy de Maupassant"], expl: "<b>Guy de Maupassant</b> (XIXᵉ siècle) a écrit des nouvelles réalistes (<i>Boule de suif</i>) et fantastiques (<i>Le Horla</i>, 1887)." },
  { q: "Combien de grandes entrées compte le programme de français du cycle 4 (sans le questionnement complémentaire) ?", answers: ["4", "quatre"], expl: "<b>Quatre</b> : Se chercher, se construire ; Vivre en société, participer à la société ; Regarder le monde, inventer des mondes ; Agir sur le monde. S’y ajoute un questionnement complémentaire." },
  { q: "Au théâtre, comment appelle-t-on les indications de jeu, de gestes ou de décor écrites par l’auteur ?", answers: ["didascalies", "les didascalies", "didascalie", "des didascalies"], expl: "Ce sont les <b>didascalies</b>, souvent en italique : elles ne sont pas dites par les comédiens mais guident la mise en scène. Elles aident beaucoup les élèves à se représenter la scène." },
  { q: "Quel genre désigne un récit bref, centré sur un événement, souvent terminé par une chute (Maupassant) ?", answers: ["nouvelle", "la nouvelle", "une nouvelle"], expl: "C’est la <b>nouvelle</b> : peu de personnages, une action resserrée, une <b>chute</b> qui surprend. Elle se prête bien à une lecture intégrale en classe." },
  { type: 'vf', q: "Dans une autobiographie, le narrateur peut être une personne différente de l’auteur.", answer: 1, expl: "<b>Faux</b> : le pacte autobiographique exige l’<b>identité</b> auteur = narrateur = personnage principal. Si le narrateur est inventé, on est dans le roman (éventuellement autobiographique)." },
  { type: 'vf', q: "Un même texte peut mêler plusieurs registres, par exemple comique et satirique.", answer: 0, expl: "<b>Vrai</b> : les registres se combinent souvent. Chez Molière, le rire (comique) sert à dénoncer un défaut (satirique). À l’écrit, repère le registre <b>dominant</b> et justifie-le." },
  { type: 'vf', q: "À l’écrit 1, il suffit de citer le texte : l’interprétation est facultative.", answer: 1, expl: "<b>Faux</b> : une citation seule ne prouve rien. Il faut <b>expliquer</b> ce qu’elle montre (effet du procédé, sens). La réponse complète : idée + citation + interprétation." },
  { type: 'vf', q: "La science-fiction et l’utopie servent souvent à interroger notre propre société.", answer: 0, expl: "<b>Vrai</b> : en imaginant d’autres mondes, ces récits font réfléchir sur le <b>réel</b> (progrès, pouvoir, liberté). C’est l’enjeu de l’entrée Regarder le monde, inventer des mondes." }
];
